#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\ndocker build -t mood-light-test . > /dev/null\n\n# Run the container with a known seed (1) and map port 5001 -> 5000\ncontainer_id=$(docker run -d -e QUOTE_SEED=1 -p 5001:5000 mood-light-test)\n\n# Give the Flask server a moment to start\nsleep 2\n\n# Query the service\nresponse=$(curl -s http://localhost:5001/)\n\n# Clean up the container\ndocker rm -f $container_id > /dev/null\n\n# Expected deterministic output for seed=1 (index 1)\nexpected='{"mood":"Dusty silence"}'\n\nif [ "$response" = "$expected" ]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: expected $expected got $response"\n  exit 1\nfi
